package com.trampolim.api.career;
import java.util.*;import java.time.*;import java.security.SecureRandom;
import static com.trampolim.api.radar.RadarModel.*;import com.trampolim.api.radar.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController public class CareerPortfolioController {
 private final JdbcTemplate jdbc;private final SkillCatalog users;private final RadarBridge bridge;
 public CareerPortfolioController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,SkillCatalog users,RadarBridge bridge){this.jdbc=jdbc;this.users=users;this.bridge=bridge;}
 public record Share(List<UUID> items,List<UUID> evidenceReceipts,String recipientEmail,String alias,int days,boolean consent){}public record Verify(int version,String token,String recipientEmail){}
 @GetMapping("/api/career/portfolio/evidence")public List<Map<String,Object>> evidence(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT e.receipt_id,e.skill_code,s.name,e.level,e.course_title,e.criterion,e.awarded_at FROM candidate_skill_evidence e JOIN skill_concepts s ON s.code=e.skill_code WHERE e.user_id=? ORDER BY e.awarded_at DESC LIMIT 100",users.user(email));}
 @GetMapping("/api/career/portfolio/shares")public List<Map<String,Object>> shares(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT id,recipient_email,alias,expires_at,revoked_at,consent_at FROM career_portfolio_shares WHERE user_id=? ORDER BY (revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP) DESC,consent_at DESC LIMIT 100",users.user(email));}
 @PostMapping("/api/career/portfolio/shares")@Transactional("oportunidadesTransactionManager")public Map<String,Object> share(@AuthenticationPrincipal String email,@RequestBody Share input){long uid=users.user(email);if(input==null||!input.consent()||input.items()==null||input.evidenceReceipts()==null||input.items().size()>20||input.evidenceReceipts().size()>20||input.items().isEmpty()&&input.evidenceReceipts().isEmpty()||input.items().stream().anyMatch(Objects::isNull)||input.evidenceReceipts().stream().anyMatch(Objects::isNull)||new HashSet<>(input.items()).size()!=input.items().size()||new HashSet<>(input.evidenceReceipts()).size()!=input.evidenceReceipts().size()||input.days()<1||input.days()>30)bad("Selecione itens próprios, destinatário, prazo de 1 a 30 dias e autorize o compartilhamento.");String recipient=text(input.recipientEmail(),180).toLowerCase(Locale.ROOT);if(!recipient.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))bad("E-mail do recrutador inválido.");jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);if(jdbc.queryForObject("SELECT count(*) FROM career_portfolio_shares WHERE user_id=? AND revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP",Integer.class,uid)>=100)bad("Revogue compartilhamentos antigos para criar outro.");var ownItems=jdbc.queryForList("SELECT id FROM career_portfolio_items WHERE user_id=?",UUID.class,uid);var ownEvidence=jdbc.queryForList("SELECT receipt_id FROM candidate_skill_evidence WHERE user_id=?",UUID.class,uid);if(!ownItems.containsAll(input.items())||!ownEvidence.containsAll(input.evidenceReceipts()))throw new ResponseStatusException(HttpStatus.NOT_FOUND);byte[] random=new byte[32];new SecureRandom().nextBytes(random);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(random);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO career_portfolio_shares(id,user_id,token_hash,recipient_email,alias,item_ids,evidence_receipts,expires_at) VALUES (?,?,?,?,?,?::jsonb,?::jsonb,?)",id,uid,RadarBridge.hash(token),recipient,text(input.alias(),80),bridge.encode(input.items()),bridge.encode(input.evidenceReceipts()),java.sql.Timestamp.from(Instant.now().plusSeconds(input.days()*86400L)));return Map.of("id",id,"token",token);}
 @DeleteMapping("/api/career/portfolio/shares/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(@AuthenticationPrincipal String email,@PathVariable UUID id){if(jdbc.update("UPDATE career_portfolio_shares SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE id=? AND user_id=?",id,users.user(email))==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
 @PostMapping("/api/integrations/career/portfolio/verify")public Map<String,Object> verify(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody Verify input){bridge.authorize(key);if(input==null||input.version()!=1||input.token()==null||!input.token().matches("[A-Za-z0-9_-]{43}"))throw new ResponseStatusException(HttpStatus.NOT_FOUND);var rows=jdbc.queryForList("SELECT s.* FROM career_portfolio_shares s JOIN app_users u ON u.id=s.user_id AND u.email_verified=TRUE WHERE s.token_hash=? AND LOWER(s.recipient_email)=LOWER(?) AND s.revoked_at IS NULL AND s.expires_at>CURRENT_TIMESTAMP",RadarBridge.hash(input.token()),input.recipientEmail());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Compartilhamento expirado, revogado ou de outro destinatário.");var share=rows.get(0);long uid=((Number)share.get("user_id")).longValue();Set<String> selected=new HashSet<>();for(var id:bridge.read(share.get("item_ids")))selected.add(id.asText());var items=jdbc.queryForList("SELECT id,kind,title,description,url,submission_receipt FROM career_portfolio_items WHERE user_id=?",uid).stream().filter(i->selected.contains(i.get("id").toString())).toList();for(var item:items){item.put("origin","DECLARED");if(item.get("submission_receipt")!=null)try{var evidence=bridge.post("/integrations/career/challenges/receipt",new CompanyCareerService.Receipt(1,(UUID)item.get("submission_receipt")));if(evidence.path("status").asText().equals("REVIEWED")&&evidence.path("revoked_at").isNull()){item.put("origin","COMPANY_CHALLENGE_REVIEW");item.put("review",Map.of("scorePercent",evidence.path("score_percent").asDouble(),"feedback",evidence.path("feedback").asText()));}else item.put("origin","EVIDENCE_NOT_ACTIVE");}catch(ResponseStatusException unavailable){item.put("origin","EVIDENCE_UNAVAILABLE");}item.remove("submission_receipt");}
  var receiptIds=new ArrayList<UUID>();for(var id:bridge.read(share.get("evidence_receipts")))receiptIds.add(UUID.fromString(id.asText()));var evidenceRows=new ArrayList<Map<String,Object>>();String evidenceStatus="AVAILABLE";if(!receiptIds.isEmpty())try{var valid=bridge.post("/integrations/capacita/radar/evidence",Map.of("receipts",receiptIds));Set<String> active=new HashSet<>();for(var r:valid)if(r.path("active").asBoolean())active.add(r.path("receiptId").asText());for(var row:jdbc.queryForList("SELECT receipt_id,skill_code,level,course_title,criterion,awarded_at FROM candidate_skill_evidence WHERE user_id=?",uid))if(receiptIds.contains(row.get("receipt_id"))&&active.contains(row.get("receipt_id").toString()))evidenceRows.add(row);}catch(ResponseStatusException unavailable){evidenceStatus="UNAVAILABLE";}
  jdbc.update("INSERT INTO career_audit(user_id,event,reference) VALUES (?,'PORTFOLIO_VERIFIED',?)",uid,share.get("id"));return Map.of("alias",share.get("alias"),"items",items,"competencies",evidenceRows,"evidenceStatus",evidenceStatus,"notice","Itens manuais são declarações. Avaliação empresarial é evidência de desafio, não certificado educacional. Credenciais do Capacita são revalidadas mediante a autorização existente.");}
}
